import functools
import time


def retry_backoff(max_attempts=3, base_delay=1.0, factor=2.0, max_delay=None,
                  retry_on=(Exception,), sleep=time.sleep):
    if max_attempts < 1:
        raise ValueError('max_attempts must be >= 1')
    if base_delay < 0:
        raise ValueError('base_delay must be >= 0')

    def compute_delay(attempt):
        delay = base_delay * factor ** (attempt - 1)
        return delay if max_delay is None else min(delay, max_delay)

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except retry_on:
                    if attempt == max_attempts:
                        raise
                    sleep(compute_delay(attempt))
        return wrapper
    return decorator


