# Test harness (do not change). sleep is injected, so delays are recorded, not slept.
# ---------------------------------------------------------------------------
def simulate(fail_times, max_attempts, base_delay=1.0, factor=2.0, max_delay=None, error="ConnectionError"):
    exc_cls = {"ConnectionError": ConnectionError, "ValueError": ValueError}[error]
